"""Generated fixed unknown-state keeper qualification; native disabled."""
import base64,json,zlib,sys
def decode_sources(payload):
    decoder = zlib.decompressobj()
    raw = decoder.decompress(payload, 131073)
    if len(raw) > 131072 or not decoder.eof or decoder.unconsumed_tail or decoder.unused_data:
        raise ValueError('composed-source-bound')
    parts = json.loads(raw.decode('utf-8', errors='strict'))
    if (type(parts) is not dict or set(parts) != {'legacy', 'policy', 'observer', 'startup', 'mount', 'extension'}
            or any(type(source) is not str for source in parts.values())):
        raise ValueError('composed-source-schema')
    return parts

parts=decode_sources(base64.b64decode('',validate=True))
NS={'__name__':'sealed_runtime_component'}
exec(parts['legacy'],NS)
POLICY={'__name__':'sealed_helper_policy'}
exec(parts['policy'],POLICY)
OBSERVER={'__name__':'sealed_startup_observer','POLICY':POLICY}
exec(parts['observer'],OBSERVER)
NS.update(POLICY=POLICY,STARTUP_OBSERVER=OBSERVER)
for component in ('startup','mount','extension'): exec(parts[component],NS)
CAPS,RESERVED=NS['CAPS'],NS['RESERVED']
if __name__=='__main__':
    NS['os'].umask(0o077)
    if 'BUNDLE' in globals():
        NS['observe']=NS['scheduled_unknown_observe']
        NS['prepare'](BUNDLE)
    else:
        role,directory,nonce=sys.argv[1:4]
        if role not in ('worker','bridge','namespace_worker','keeper','observe','unknown_observe'):
            raise ValueError('fixed-unknown-keeper-role')
        NS[role](NS['Path'](directory),nonce)
